INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 10, 'theory', 'Quiz: pre-copy, post-copy, and dirty pages');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 10, 0, 'What are dirty pages in live migration?', '["Corrupted pages", "Pages changed by the guest after they were sent", "Pages filled with zeros", "Hypervisor pages"]', 1, 'In each pre-copy round, only the pages that became dirty during the previous round are sent.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 10, 1, 'When does pre-copy converge?', '["When the guest''s memory write rate is lower than the network bandwidth", "When the guest is powered off", "When memory is larger than the disk", "Always"]', 0, 'Otherwise the remainder doesn''t shrink: throttling the guest, compression, or post-copy can help.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 10, 2, 'What does post-copy do?', '["Copies everything before starting on the target", "Stops the guest for a minute", "Switches the guest to the target first, and pulls pages on demand via userfaultfd", "Compresses the disk"]', 2, 'Each page is sent exactly once, so migration always finishes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 10, 3, 'What is the main risk of post-copy?', '["It loses on speed", "It never finishes", "It requires a license", "While pages are scattered between the servers, a network failure or a failure of either server destroys the machine"]', 3, 'With pre-copy the original copy stays intact until the very end, so a rollback is possible.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 10, 4, 'How does the page-modification log (PML) speed up dirty page tracking?', '["It disables writes to memory", "The hardware itself writes the addresses of modified pages into a log, and an exit is needed only when it fills up", "It compresses the guest''s memory", "It copies pages in the background"]', 1, 'Without PML, every first write to a page causes a nested page table fault.');
